sources.src/features/assessment/schedule/index.t:
export { scheduleAssessment } from "./domain/use-cases/schedule-assessment";
export type { Schedule, ScheduleRequest } from "./domain/models/schedule";
export { useSchedule } from "./ui/hooks/use-schedule";

sources.src/features/assessment/schedule/domain/:
export interface ScheduleRequest {
  assessmentId: string;
  classId: string;
  releaseAt: string;
}

export interface Schedule {
  scheduleId: string;
}

import type { ScheduleRequest } from "../models/schedule";

export function isFutureRelease(request: ScheduleRequest, now: Date): boolean {
  return Date.parse(request.releaseAt) > now.getTime();
}

import { scheduleClient } from "../../client/schedule-client";
import type { Schedule, ScheduleRequest } from "../models/schedule";
import { isFutureRelease } from "../policies/release-time";

export async function scheduleAssessment(request: ScheduleRequest, now: Date): Promise<Schedule> {
  if (!isFutureRelease(request, now)) throw new Error("invalid-time");
  return scheduleClient.schedule(request);
}

sources.src/features/assessment/schedule/client/:
import { generateClient } from "aws-amplify/data";
import type { Schedule, ScheduleRequest } from "../domain/models/schedule";

const client = generateClient();

export const scheduleClient = {
  async schedule(request: ScheduleRequest): Promise<Schedule> {
    const result = await client.mutations.scheduleAssessment(request);
    return { scheduleId: result.data.scheduleId };
  },
};

sources.src/features/assessment/schedule/ui/hook:
import type { ScheduleRequest } from "../../domain/models/schedule";
import { scheduleAssessment } from "../../domain/use-cases/schedule-assessment";

export function useSchedule() {
  return (request: ScheduleRequest) => scheduleAssessment(request, new Date());
}

sources.src/features/assessment/schedule/ui/scre:
